.row-hover-actions .icon-button { width: 31px; height: 31px; }
.row-star-placeholder { width: 24px; }
.draft-avatar { color: #bd7773; background: #f7e9e5; }
.draft-sender { color: #c16d67; }
.draft-recipient { color: var(--muted); font-size: 10px; }
.list-footer { height: 50px; display: flex; justify-content: space-between; align-items: center; gap: 12px; padding: 0 39px; color: #a9b2c0; font-size: 10.5px; }
.list-footer > span:last-child { display: flex; align-items: center; gap: 5px; white-space: nowrap; }
.list-footer kbd { font-size: 10px; padding: 1px 4px; }
.empty-state { text-align: center; padding: 65px 20px 72px; }
.empty-art { margin: 0 auto 18px; width: 66px; height: 66px; display: grid; place-items: center; border-radius: 19px; background: var(--primary-soft); color: var(--primary); }
.empty-state h3 { font: 800 18px Manrope, sans-serif; margin: 0 0 8px; color: var(--text-strong); }
.empty-state p { color: var(--muted); margin: 0; font-size: 13px; }
.empty-action { border: 0; background: var(--primary); color: white; padding: 10px 15px; border-radius: 8px; font-size: 12px; font-weight: 700; margin-top: 19px; }
.relative { position: relative; }
.popover { position: absolute; z-index: 20; background: var(--panel); border: 1px solid var(--line); box-shadow: 0 16px 48px rgba(36, 45, 75, .16); border-radius: 12px; color: var(--text); }
.label-popover { left: 0; top: calc(100% + 7px); width: 210px; padding: 8px; }
.popover-heading { font-size: 11px; font-weight: 800; color: var(--muted-dark); padding: 9px 10px; }
.label-option { width: 100%; height: 32px; border: 0; border-radius: 6px; background: transparent; color: var(--text); display: flex; align-items: center; gap: 9px; padding: 0 9px; text-align: left; font-size: 12px; }
.label-option:hover, .account-popover > button:hover { background: var(--hover); }
.mini-check { width: 14px; height: 14px; display: grid; place-items: center; border: 1px solid #bdc6d4; border-radius: 3px; }
.mini-check.checked { background: var(--primary); border-color: var(--primary); color: white; }
.label-dot { width: 7px; height: 7px; border-radius: 50%; }
.popover-divider { height: 1px; background: var(--line); margin: 7px 0; }
.new-label { display: flex; align-items: center; padding: 3px 5px; }
.new-label input { width: 100%; min-width: 0; border: 0; background: transparent; outline: 0; color: var(--text); font-size: 12px; padding: 7px; }
.new-label button { border: 0; background: var(--primary-soft); color: var(--primary); width: 27px; height: 27px; display: grid; place-items: center; border-radius: 6px; }
.account-popover { width: 288px; right: 0; top: 47px; padding: 10px; }
.account-card { display: flex; gap: 11px; align-items: center; padding: 9px 8px 13px; }
.account-card div { min-width: 0; display: flex; flex-direction: column; gap: 3px; }
.account-card strong { font-size: 12px; }
.account-card div span { font-size: 10px; color: var(--muted); overflow: hidden; text-overflow: ellipsis; }
.account-popover > button { width: 100%; border: 0; background: transparent; color: var(--text); display: flex; align-items: center; gap: 10px; padding: 9px 10px; border-radius: 6px; text-align: left; font-size: 11.5px; }
.account-popover > button svg { color: var(--muted-dark); }
.account-popover p { margin: 9px 10px 4px; font-size: 10px; color: var(--muted); }
.thread-toolbar { min-height: 58px; padding: 0 29px; }
.thread-toolbar .icon-button:first-child { margin-right: 8px; }
.thread-content { max-width: 980px; padding: 37px 58px 90px; }
.thread-title-row { display: flex; justify-content: space-between; align-items: start; gap: 15px; margin-bottom: 30px; }
.thread-title-row h2 { font-size: 26px; line-height: 1.3; }
.thread-title-row .icon-button { margin-top: 19px; }
.thread-labels { display: flex; gap: 6px; margin-top: 12px; }
.conversation { display: flex; flex-direction: column; gap: 14px; }
.message-card { border: 1px solid var(--line); border-radius: 12px; overflow: hidden; background: var(--panel); }
.message-card.expanded { box-shadow: 0 6px 22px rgba(31, 47, 85, .035); }
.message-heading { width: 100%; border: 0; background: transparent; color: var(--text); display: flex; gap: 12px; align-items: center; text-align: left; padding: 19px 22px; }
.message-heading:hover { background: var(--hover); }
.sender-avatar { width: 38px; height: 38px; font-size: 12px; border-radius: 12px; }
.message-sender-details { display: flex; flex-direction: column; gap: 3px; min-width: 0; flex: 1; }
.message-sender-details strong { color: var(--text-strong); font-size: 13px; }
.message-sender-details span { color: var(--muted); font-size: 11px; overflow: hidden; white-space: nowrap; text-overflow: ellipsis; }
.message-date { font-size: 10.5px; color: var(--muted); white-space: nowrap; }
.message-heading > svg:last-child { color: var(--muted); transition: transform .15s; }
.message-card.expanded .message-heading > svg:last-child { transform: rotate(180deg); }
.message-expanded-content { padding: 0 24px 25px 72px; }
.sender-email { margin: -3px 0 23px; color: #9da7b5; font-size: 10px; }
.message-body { font-size: 13px; line-height: 1.65; color: var(--text); max-width: 750px; }
.message-body p { margin: 0; min-height: 10px; }
.attachments { margin-top: 28px; }
.attachment-label { display: flex; align-items: center; gap: 6px; color: var(--muted-dark); font-size: 11px; font-weight: 700; margin-bottom: 10px; }
.attachment-list { display: flex; gap: 8px; flex-wrap: wrap; }
.attachment-card { display: flex; align-items: center; gap: 9px; width: 215px; max-width: 100%; height: 52px; border: 1px solid var(--line); background: var(--panel); border-radius: 8px; color: var(--muted-dark); padding: 0 12px; text-align: left; }
.attachment-card:hover { border-color: var(--primary); background: var(--hover); }
.attachment-card > svg:first-child { color: var(--primary); flex: 0 0 auto; }
.attachment-card span { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: 10.5px; font-weight: 700; flex: 1; }
.thread-reply-actions { display: flex; gap: 9px; margin: 25px 0 0 72px; }
.thread-reply-actions button { border: 1px solid #dce2ec; background: var(--panel); color: var(--muted-dark); border-radius: 8px; display: flex; align-items: center; gap: 8px; padding: 9px 15px; font-size: 11.5px; font-weight: 700; }
.thread-reply-actions button:hover { border-color: var(--primary); color: var(--primary); }
.compose-window { position: fixed; z-index: 30; right: 30px; bottom: 0; width: min(540px, calc(100vw - 20px)); height: min(600px, calc(100vh - 88px)); display: flex; flex-direction: column; background: var(--panel); border: 1px solid var(--line); border-radius: 13px 13px 0 0; box-shadow: 0 14px 65px rgba(24, 35, 63, .24); overflow: hidden; }

